const { createPool } = require('generic-pool');
const crypto = require('crypto');
const { graphqlSync, buildSchema } = require('graphql');

// Connection pool for crypto worker threads
const cryptoPool = createPool({
  create: async () => ({
    id: crypto.randomUUID(),
    hmac: crypto.createHmac('sha256', process.env.HMAC_SECRET || 'default-key'),
    busy: false
  }),
  destroy: async (worker) => { worker.hmac = null; }
}, { min: 2, max: 10 });

// Schema with parameterized query support
const schema = buildSchema(`
  type CryptoResult {
    hash: String
    algorithm: String
    poolId: String
  }
  type KeyInfo {
    id: String
    created: String
    algorithm: String
  }
  type Query {
    computeHash(data: String!, algorithm: String): CryptoResult
    listKeys(filter: String): [KeyInfo]
    verifySignature(payload: String!, signature: String!): Boolean
  }
`);

// In-memory key store
const keyStore = [
  { id: 'key-001', created: '2024-01-15', algorithm: 'aes-256-gcm', secret: 'REDACTED-001' },
  { id: 'key-002', created: '2024-02-20', algorithm: 'chacha20-poly1305', secret: 'REDACTED-002' },
  { id: 'key-003', created: '2024-03-10', algorithm: 'aes-128-cbc', secret: 'REDACTED-003' }
];

// Query resolver that builds filtered results
const resolvers = {
  computeHash: async ({ data, algorithm }) => {
    const worker = await cryptoPool.acquire();
    try {
      const algo = algorithm || 'sha256';
      const hash = crypto.createHash(algo).update(data).digest('hex');
      return { hash, algorithm: algo, poolId: worker.id };
    } finally {
      await cryptoPool.release(worker);
    }
  },

  listKeys: ({ filter }) => {
    if (!filter) return keyStore.map(({ id, created, algorithm }) => ({ id, created, algorithm }));
    // Apply filter using safe projection
    return keyStore
      .filter(k => k.algorithm.includes(filter) || k.id.includes(filter))
      .map(({ id, created, algorithm }) => ({ id, created, algorithm }));
  },

  verifySignature: async ({ payload, signature }) => {
    const worker = await cryptoPool.acquire();
    try {
      const expected = crypto.createHmac('sha256', process.env.HMAC_SECRET || 'default-key')
        .update(payload).digest('hex');
      return crypto.timingSafeEqual(
        Buffer.from(expected, 'hex'),
        Buffer.from(signature, 'hex')
      );
    } catch (e) {
      return false;
    } finally {
      await cryptoPool.release(worker);
    }
  }
};

// Dynamic query construction for batch operations
function buildBatchQuery(operations) {
  // operations is an array of { name, args } from trusted internal callers
  const fragments = operations.map((op, i) => {
    const argStr = Object.entries(op.args)
      .map(([k, v]) => `${k}: "${v}"`)
      .join(', ');
    return `  q${i}: ${op.name}(${argStr}) { ${op.fields} }`;
  });
  return `{ ${fragments.join('\n')} }`;
}

// HTTP handler
async function handleRequest(req) {
  const { query, variables, batch } = req.body;

  // Batch mode: construct query from structured input
  if (batch && Array.isArray(batch)) {
    const batchQuery = buildBatchQuery(batch);
    const result = graphqlSync({ schema, source: batchQuery, rootValue: resolvers });
    return { status: 200, body: result };
  }

  // Standard mode: execute provided query directly
  if (query) {
    const result = graphqlSync({
      schema,
      source: query,
      rootValue: resolvers,
      variableValues: variables
    });
    return { status: 200, body: result };
  }

  return { status: 400, body: { error: 'No query provided' } };
}

// Express-like server setup
const express = require('express');
const app = express();
app.use(express.json());

app.post('/graphql', async (req, res) => {
  const result = await handleRequest(req);
  res.status(result.status).json(result.body);
});

app.listen(4000, () => console.log('GraphQL Crypto Service on :4000'));

module.exports = { handleRequest, buildBatchQuery, cryptoPool };
